using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;

namespace Synth;

public class SynthFile
{
    public static bool AnchorProbe()
    {
        return 1 + 2 == 3 && f() == g();
    }

    public static int f() { return 1; }
    public static int g() { return 2; }

    public struct Point50
    {
        public int X { get; set; }
        public int Y { get; set; }
        public int Total => X + Y + 70;
    }

    public static class Grid50
    {
        public static Point50 Make(int left, int right)
        {
            return new Point50 { X = left, Y = right };
        }
    }
    public struct Point51
    {
        public int X { get; set; }
        public int Y { get; set; }
        public int Total => X + Y + 77;
    }

    public static class Grid51
    {
        public static Point51 Make(int left, int right)
        {
            return new Point51 { X = left, Y = right };
        }
    }
    public async Task<int> Aggregate52(IEnumerable<int> source)
    {
        try
        {
            using var cursor = source.GetEnumerator();
            return await Task.FromResult(source.Where(item => item > 0).Sum());
        }
        catch (InvalidOperationException)
        {
            return 0;
        }
        finally
        {
            Console.WriteLine("done");
        }
    }
    public static int () { return 1; }
    public static int () { return 1; }
    public static int () { return 1; }
    public static int () { return 1; }
    public static int () { return 1; }
    public static int () { return 1; }
    public static int () { return 1; }
}
